CREATE TABLE qc_roles (id VARCHAR(48) PRIMARY KEY, title VARCHAR(191) NOT NULL, permissions JSON NOT NULL) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
INSERT INTO qc_roles VALUES ('admin','系统管理员',JSON_ARRAY()), ('member','成员',JSON_ARRAY());
CREATE TABLE qc_accounts (id CHAR(36) PRIMARY KEY, login VARCHAR(80) NOT NULL UNIQUE, displayName VARCHAR(191) NOT NULL, passwordHash VARCHAR(191) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, roleId VARCHAR(48) NOT NULL, FOREIGN KEY (roleId) REFERENCES qc_roles(id)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE qc_sessions (digest CHAR(64) PRIMARY KEY, accountId CHAR(36) NOT NULL, expiresAt DATETIME(3) NOT NULL, INDEX (expiresAt), FOREIGN KEY (accountId) REFERENCES qc_accounts(id) ON DELETE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
